 CONSTRAINT `chk_comer_status` CHECK (`status` IN (''satisfied'',''under_minimum'',''dean_recommended'',''continued_exceptionally'',''closure_pending'',''cancelled'',''superseded'')),
 CONSTRAINT `chk_comer_dean` CHECK ((`dean_recommendation` IS NULL AND `dean_user_id` IS NULL AND `dean_notes` IS NULL AND `dean_recommended_at` IS NULL) OR (`dean_recommendation` IN (''continue'',''cancel'') AND `dean_user_id` IS NOT NULL AND NULLIF(TRIM(`dean_notes`),'''') IS NOT NULL AND `dean_recommended_at` IS NOT NULL)),
 CONSTRAINT `chk_comer_dean_status` CHECK (`status`<>''dean_recommended'' OR `dean_recommendation` IS NOT NULL),
 CONSTRAINT `chk_comer_scientific` CHECK ((`scientific_decision` IS NULL AND `scientific_user_id` IS NULL AND `scientific_notes` IS NULL AND `scientific_decided_at` IS NULL) OR (`scientific_decision` IN (''continue'',''cancel'') AND `scientific_user_id` IS NOT NULL AND NULLIF(TRIM(`scientific_notes`),'''') IS NOT NULL AND `scientific_decided_at` IS NOT NULL)),
 CONSTRAINT `chk_comer_terminal` CHECK ((`status`<>''continued_exceptionally'' OR (`scientific_decision`=''continue'' AND `continued_at` IS NOT NULL)) AND (`status`<>''closure_pending'' OR (`scientific_decision`=''cancel'' AND `course_offering_closure_request_id` IS NOT NULL)) AND (`status`<>''cancelled'' OR (`scientific_decision`=''cancel'' AND `course_offering_closure_request_id` IS NOT NULL AND `cancelled_at` IS NOT NULL AND `affected_registration_count` IS NOT NULL)) AND (`status`<>''superseded'' OR `superseded_at` IS NOT NULL)),
 CONSTRAINT `fk_comer_semester_request` FOREIGN KEY (`semester_offering_request_id`) REFERENCES `alrowad_uni_rust`.`semester_offering_requests` (`semester_offering_request_id`) ON UPDATE RESTRICT ON DELETE RESTRICT,
