 CONSTRAINT `chk_srrpr_return` CHECK (`status`<>''returned'' OR (`advisor_user_id` IS NOT NULL AND `reviewed_at` IS NOT NULL AND NULLIF(TRIM(`advisor_notes`),'''') IS NOT NULL)),
